package com.example.evolveumrest.mapper;

import com.example.evolveumrest.dto.UserDto;
import com.example.evolveumrest.model.User;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.mapstruct.MappingConstants;
import org.mapstruct.ReportingPolicy;

/**
 * Converts users between the REST API format (UserDto) and the database entity (User).
 * The implementation is generated by MapStruct at compile time (target/generated-sources).
 */
@Mapper(componentModel = MappingConstants.ComponentModel.SPRING, unmappedTargetPolicy = ReportingPolicy.ERROR)
public interface UserMapper {

    /**
     * "policy" is calculated by the system, a value sent by the client is ignored.
     * "version" is managed by JPA and is not part of the API.
     */
    @Mapping(target = "policy", ignore = true)
    @Mapping(target = "version", ignore = true)
    User toEntity(UserDto dto);

    UserDto toDto(User user);
}
